#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
grep -q '^# room' "$t" || { echo "header line lost"; fail=1; }
grep -q '^kaede.2026-01-05.13:00' "$t" || { echo "other booking lost"; fail=1; }
err=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>&1 >/dev/null); rc=$?
[ "$rc" = 1 ] || { echo "not found should exit 1, got $rc"; fail=1; }
[ "$err" = 'not found: aoi 2026-01-05 11:00' ] || { echo "not found message on stderr: $err"; fail=1; }
rm -f "$t"

u=$(mktemp); printf '# room\tdate\tstart\tend\twho\nkaede\t2026-01-05\t09:00\t10:00\tz\naoi\t2026-01-05\t09:00\t10:00\tx\n' > "$u"
BOOKINGS=$u bash src/cancel.sh aoi 2026-01-05 09:00 >/dev/null || { echo "room cancel failed"; fail=1; }
grep -q '^kaede.2026-01-05.09:00' "$u" || { echo "other room's booking removed with aoi"; fail=1; }
rm -f "$u"

so=$(bash src/cancel.sh aoi 2026-01-05 2>/dev/null); rc=$?
[ "$rc" = 2 ] || { echo "usage should exit 2, got $rc"; fail=1; }
[ -z "$so" ] || { echo "usage should not print to stdout: $so"; fail=1; }
se=$(bash src/cancel.sh aoi 2026-01-05 2>&1 >/dev/null)
[ "$se" = 'usage: cancel.sh ROOM DATE START' ] || { echo "usage message on stderr: $se"; fail=1; }
exit $fail

