t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
grep -q '^# room' "$t" || { echo "header line lost"; fail=1; }
grep -q '^kaede' "$t" || { echo "other booking (kaede) lost"; fail=1; }
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 >/dev/null 2>&1; [ $? = 1 ] || { echo "not found should exit 1"; fail=1; }
nf_out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>/dev/null); [ -z "$nf_out" ] || { echo "not found should print nothing to stdout: $nf_out"; fail=1; }
nf_err=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>&1 >/dev/null); [ "$nf_err" = 'not found: aoi 2026-01-05 11:00' ] || { echo "not found message on stderr: $nf_err"; fail=1; }
u_out=$(bash src/cancel.sh aoi 2>/dev/null); u_rc=$?; [ "$u_rc" = 2 ] || { echo "usage should exit 2, got $u_rc"; fail=1; }
[ -z "$u_out" ] || { echo "usage should print nothing to stdout: $u_out"; fail=1; }
u_err=$(bash src/cancel.sh aoi 2>&1 >/dev/null); [ "$u_err" = 'usage: cancel.sh ROOM DATE START' ] || { echo "usage text on stderr: $u_err"; fail=1; }
t2=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t09:00\t10:00\ty\n' > "$t2"
