#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
grep -q '^# room' "$t" && grep -q '^kaede.2026-01-05.13:00.14:00.y$' "$t" || { echo "header or other booking lost"; fail=1; }
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 >/dev/null 2>&1; [ $? = 1 ] || { echo "not found should exit 1"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>/dev/null)" ] || { echo "not found should print nothing to stdout"; fail=1; }
BOOKINGS=$t bash src/cancel.sh aoi >/dev/null 2>&1; [ $? = 2 ] || { echo "wrong arg count should exit 2"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/cancel.sh aoi 2>/dev/null)" ] || { echo "usage should print nothing to stdout"; fail=1; }
rm -f "$t"
t2=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t09:00\t10:00\ty\n' > "$t2"
BOOKINGS=$t2 bash src/cancel.sh aoi 2026-01-05 09:00 >/dev/null || { echo "cancel in same slot failed"; fail=1; }
grep -q '^kaede.2026-01-05.09:00.10:00.y$' "$t2" && ! grep -q '^aoi' "$t2" || { echo "other room's booking in same slot was removed"; fail=1; }
rm -f "$t2"; exit $fail

