#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\nkaede\t2026-01-05\t09:00\t10:00\tz\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
grep -q '^# room' "$t" || { echo "header line lost"; fail=1; }
grep -q '^kaede.2026-01-05.13:00' "$t" || { echo "other booking (kaede 13:00) lost"; fail=1; }
grep -q '^kaede.2026-01-05.09:00' "$t" || { echo "same date and start in another room (kaede 09:00) lost"; fail=1; }
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 >/dev/null 2>&1; [ $? = 1 ] || { echo "not found should exit 1"; fail=1; }
o=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>/dev/null); [ -z "$o" ] || { echo "not found: stdout should be empty, got: $o"; fail=1; }
e=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>&1 >/dev/null); [ "$e" = 'not found: aoi 2026-01-05 11:00' ] || { echo "not found: stderr message: $e"; fail=1; }
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 >/dev/null 2>&1; [ $? = 2 ] || { echo "wrong arg count should exit 2"; fail=1; }
e=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 2>&1 >/dev/null); [ "$e" = 'usage: cancel.sh ROOM DATE START' ] || { echo "usage message: $e"; fail=1; }
o=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 2>/dev/null); [ -z "$o" ] || { echo "usage: stdout should be empty, got: $o"; fail=1; }
rm -f "$t"; exit $fail

