grep -q '^aoi.2026-01-05.09:00' "$t" && { echo "aoi booking still there"; fail=1; }
rm -f "$t"

# 引数の数が違うときは usage を stderr に出し、exit 2
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\n' > "$t"
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 >/dev/null 2>/dev/null; [ $? = 2 ] || { echo "usage should exit 2"; fail=1; }
o=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 2>/dev/null); [ -z "$o" ] || { echo "usage should print nothing to stdout: $o"; fail=1; }
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 2>&1 >/dev/null | grep -q '^usage: cancel.sh ROOM DATE START$' || { echo "usage message should be on stderr"; fail=1; }
rm -f "$t"
exit $fail

